from collections import deque
def objs(g, bg):
    seen=set(); out=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j]!=bg and (i,j) not in seen:
                col=g[i][j]; q=deque([(i,j)]); seen.add((i,j)); cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<len(g) and 0<=nx<len(g[0]) and (ny,nx) not in seen and g[ny][nx]!=bg:
                                seen.add((ny,nx)); q.append((ny,nx))
                ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
                h=max(ys)-min(ys)+1; w=max(xs)-min(xs)+1
                pat=tuple(tuple(1 if (min(ys)+r,min(xs)+c) in set(cells) else 0 for c in range(w)) for r in range(h))
                out.append({'color':col,'cells':sorted(cells),'h':h,'w':w,'n':len(cells),'pat':pat,'bbox':(min(ys),min(xs))})
    return out
def norm(pat):
    # trim empty rows/cols
    rows=[i for i,r in enumerate(pat) if any(r)]
    cols=[j for j in range(len(pat[0])) if any(r[j] for r in pat)]
    return tuple(tuple(pat[i][j] for j in cols) for i in rows)
