def components(g, bg, conn=8):
    seen=set(); out=[]
    H,W=len(g),len(g[0])
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                col=g[i][j]; q=deque([(i,j)]); seen.add((i,j)); cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    nb=[(y+1,x),(y-1,x),(y,x+1),(y,x-1)]
                    if conn==8: nb+= [(y+1,x+1),(y+1,x-1),(y-1,x+1),(y-1,x-1)]
                    for ny,nx in nb:
                        if 0<=ny<H and 0<=nx<W and (ny,nx) not in seen and g[ny][nx]!=bg:
                            seen.add((ny,nx)); q.append((ny,nx))
                out.append((col,cells))
    return out
